<?php
namespace App\Console\Commands;
use App\Jobs\SendEmailJob;use App\Models\User;use App\Models\UserCoupon;use Illuminate\Console\Command;use Illuminate\Support\Facades\DB;use Illuminate\Support\Facades\Schema;
class CheckUserCoupons extends Command { protected $signature='coupon:check-wallet';protected $description='更新优惠券状态并发送到期提醒';public function handle(){if(!Schema::hasTable('v2_user_coupon'))return 0;$now=time();UserCoupon::whereIn('status',['pending','available'])->where('expires_at','<',$now)->update(['status'=>'expired','updated_at'=>$now]);UserCoupon::where('status','pending')->where('starts_at','<=',$now)->where('expires_at','>=',$now)->update(['status'=>'available','updated_at'=>$now]);$coupons=UserCoupon::with('template')->where('status','available')->whereBetween('expires_at',[$now+2*86400,$now+3*86400])->get();$users=User::whereIn('id',$coupons->pluck('user_id'))->pluck('email','id');foreach($coupons as $c){$exists=DB::table('v2_coupon_operation_record')->where('user_coupon_id',$c->id)->where('action','expiry_reminded')->exists();if($exists)continue;$email=$users->get($c->user_id);if(!$email)continue;SendEmailJob::dispatch(['email'=>$email,'subject'=>'优惠券即将到期','template_name'=>'notify','template_value'=>['name'=>config('v2board.app_name','V2Board'),'url'=>config('v2board.app_url'),'content'=>'您的优惠券「'.($c->template?$c->template->name:'').'」将于 '.date('Y-m-d H:i',$c->expires_at).' 到期，请及时使用。']]);DB::table('v2_coupon_operation_record')->insert(['user_coupon_id'=>$c->id,'user_id'=>$c->user_id,'action'=>'expiry_reminded','detail'=>'{}','created_at'=>$now]);}return 0;} }
